<?php require_once __DIR__.'/bootstrap.php'; if(current_user()){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)$error='Enter a valid name/email and a password of at least 10 characters.';else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];header('Location: index.php');exit;}catch(PDOException $e){$error=$e->getCode()==='23000'?'That email is already registered.':'Registration failed. Please try again.';}}} page_start('Create account'); ?>
<div class="panel" style="max-width:520px;margin:auto"><h1>Create your account</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name</label><input name="name" required maxlength="120" autocomplete="name"><label>Email</label><input type="email" name="email" required autocomplete="email"><label>Password (10+ characters)</label><input type="password" name="password" minlength="10" required autocomplete="new-password"><button>Create account</button></form><p>Already registered? <a href="login.php">Sign in</a></p></div><?php page_end(); ?>
